func validatePort(port: int) -> bool {
  port >= 1024 && port <= 65535
}

func countDots_aux(chars: List[char], count: int) -> int {
    match chars {
        [] => count,
        ::(h, t) => if h == '.' then countDots_aux(t, count + 1) else countDots_aux(t, count)
    }
}

func validateVersion(ver: string) -> bool {
    countDots_aux(_str_to_list(ver), 0) == 2
}

func getField(kvs: List[{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    ::(kv, rest) => if kv.key == target then kv.value else getField(rest, target)
  }
}

func jsonToString(j: Json) -> string {
  match j {
    JString(s) => s,
    _ => ""
  }
}

func jsonToInt(j: Json) -> int {
  match j {
    JNumber(f) => floatToInt(f),
    _ => 0
  }
}

func jsonToStringList_aux(js: List[Json]) -> List[string] {
    match js {
        [] => [],
        ::(h, t) => ::(jsonToString(h), jsonToStringList_aux(t))
    }
}

func jsonToStringList(j: Json) -> List[string] {
    match j {
        JArray(items) => jsonToStringList_aux(items),
        _ => []
    }
}

func loadConfig(filename: string) -> Config ! {FS} {
  let content = readFile(filename);
  match decode(content) {
    Err(_) => defaultConfig,
    Ok(json) => match json {
      JObject(kvs) => {
        let app_name = jsonToString(getField(kvs, "app_name"));
        let version = jsonToString(getField(kvs, "version"));
        let port = jsonToInt(getField(kvs, "port"));
        let features = jsonToStringList(getField(kvs, "features"));

        if validatePort(port) && validateVersion(version) && !(length(features) == 0)
        then { app_name: app_name, version: version, port: port, features: features }
        else defaultConfig
      },
      _ => defaultConfig
    }
  }
}

export func main() -> () ! {IO, FS} {
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  let _ = writeFile("app_config.json", configJson);

  let config = loadConfig("app_config.json");

  let numFeatures = length(config.features);
  print("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")
}

