from __future__ import annotations

import json
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, List


@dataclass(frozen=True)
class Config:
    app_name: str
    version: str
    port: int
    features: List[str]


class ConfigError(Exception):
    pass


def validate_port(port: int) -> None:
    if not (1024 <= port <= 65535):
        raise ConfigError(f"Invalid port: {port}. Must be between 1024 and 65535.")


def validate_version(version: str) -> None:
    if version.count(".") != 2:
        raise ConfigError(f"Invalid version: {version}. Must be in X.Y.Z format.")


def validate_features(features: Any) -> List[str]:
    if not isinstance(features, list):
        raise ConfigError("Features must be a list.")
    if not features:
        raise ConfigError("Features list must not be empty.")
    str_features: List[str] = []
    for idx, item in enumerate(features):
        if not isinstance(item, str):
            raise ConfigError(f"Feature at index {idx} is not a string.")
        str_features.append(item)
    return str_features


def load_config(filename: str) -> Config:
    path = Path(filename)
    try:
        content = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise ConfigError(f"Failed to read file '{filename}': {exc}") from exc

    try:
        data = json.loads(content)
    except json.JSONDecodeError as exc:
        raise ConfigError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ConfigError("Top-level JSON must be an object.")

    try:
        app_name = data["app_name"]
        version = data["version"]
        port = data["port"]
        features_raw = data["features"]
    except KeyError as exc:
        raise ConfigError(f"Missing required field: {exc.args[0]}") from exc

    if not isinstance(app_name, str):
        raise ConfigError("Field 'app_name' must be a string.")
    if not isinstance(version, str):
        raise ConfigError("Field 'version' must be a string.")
    if not isinstance(port, int):
        raise ConfigError("Field 'port' must be an integer.")

    features = validate_features(features_raw)
    validate_port(port)
    validate_version(version)

    return Config(app_name=app_name, version=version, port=port, features=features)


def write_default_config(path: Path) -> None:
    content = (
        '{\n'
        '  "app_name": "MyApp",\n'
        '  "version": "1.0.0",\n'
        '  "port": 8080,\n'
        '  "features": ["logging", "auth", "api"]\n'
        '}\n'
    )
    path.write_text(content, encoding="utf-8")


def main() -> None:
    config_path = Path("app_config.json")
    write_default_config(config_path)

    try:
        config = load_config(str(config_path))
    except ConfigError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    num_features = len(config.features)
    print(
        f"Loaded {config.app_name} v{config.version} on port {config.port} "
        f"with {num_features} features"
    )


if __name__ == "__main__":
    main()

