type Option[a] = Some(a) | None

type User = {name: string, age: int, email: string}

func split(s: string, delim: string) -> List[string] {
    let i = _str_find(s, delim);
    if i < 0 then {
        if _str_len(s) > 0 then [s] else []
    } else {
        let head = _str_slice(s, 0, i);
        let tail_start = i + _str_len(delim);
        let tail = _str_slice(s, tail_start, _str_len(s));
        ::(head, split(tail, delim))
    }
}

func parseInt(s: string) -> Option[int] {
  func loop(chars: List[char], acc: int) -> Option[int] {
    match chars {
      [] => Some(acc),
      ::(c, cs) => {
        let code = _char_code(c);
        if code >= 48 && code <= 57 then {
          loop(cs, acc * 10 + (code - 48))
        } else {
          None
        }
      }
    }
  }
  if _str_eq(s, "") then None else loop(_str_chars(s), 0)
}

func contains(s: string, sub: string) -> bool {
  _str_find(s, sub) >= 0
}

func map[a, b](f: a -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    ::(h, t) => ::(f(h), map(f, t))
  }
}

func length[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    ::(_, t) => 1 + length(t)
  }
}

func parseRow(line: string) -> Option[User] {
  match split(line, ",") {
    [name, ageStr, email] => {
      match parseInt(ageStr) {
        Some(age) => {
          if age > 0 && contains(email, "@") then
            Some({name: name, age: age, email: email})
          else
            None
        },
        None => None
      }
    },
    _ => None
  }
}

func processRows(lines: List[string]) -> List[User] {
  match lines {
    [] => [],
    ::(line, rest) => {
      match parseRow(line) {
        Some(user) => ::(user, processRows(rest)),
        None => processRows(rest)
      }
    }
  }
}

func userToJson(user: User) -> Json {
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))),
    kv("email", js(user.email))
  ])
}

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com";
  writeFile("users.csv", csvContent);

  let fileContent = readFile("users.csv");
  let allLines = split(fileContent, "\n");

  match allLines {
    [] => print("Error: CSV file is empty"),
    ::(_, dataLines) => {
      let validUsers = processRows(dataLines);
      let jsonUsers = map(userToJson, validUsers);
      let jsonArray = ja(jsonUsers);
      let jsonOutput = encode(jsonArray);

      writeFile("users.json", jsonOutput);

      let count = length(validUsers);
      print("Converted " ++ show(count) ++ " valid rows to users.json")
    }
  }
}

