from typing import TypeVar, Generic, Callable

T = TypeVar('T')

class Pure(Generic[T]):
    """Type wrapper to mark pure functions - cannot call effectful functions"""
    def __init__(self, func: Callable[..., T]):
        self.func = func

    def __call__(self, *args, **kwargs) -> T:
        return self.func(*args, **kwargs)

class Effect(Generic[T]):
    """Type wrapper to mark effectful functions - can call pure functions"""
    def __init__(self, func: Callable[..., T]):
        self.func = func

    def __call__(self, *args, **kwargs) -> T:
        return self.func(*args, **kwargs)

# Pure functions - cannot call effectful functions
@Pure
def double(x: int) -> int:
    return x * 2

@Pure
def add(a: int, b: int) -> int:
    return a + b

# Effectful functions - can call pure functions
@Effect
def printResult(label: str, value: int) -> None:
    print(f"{label}: {value}")

@Effect
def compute_and_print() -> None:
    result1 = double(5)
    result2 = add(result1, 3)
    printResult("Result", result2)

if __name__ == "__main__":
    compute_and_print()

