from typing import TypeVar, Generic, Callable, Union, final

T = TypeVar('T')
U = TypeVar('U')
E = TypeVar('E')

@final
class Ok(Generic[T]):
    __match_args__ = ('value',)

    def __init__(self, value: T):
        self.value = value

    def __repr__(self) -> str:
        return f"Ok({self.value!r})"

    def and_then(self, func: Callable[[T], 'Result[U, E]']) -> 'Result[U, E]':
        return func(self.value)

@final
class Err(Generic[E]):
    __match_args__ = ('error',)

    def __init__(self, error: E):
        self.error = error

    def __repr__(self) -> str:
        return f"Err({self.error!r})"

    def and_then(self, func: Callable[[T], 'Result[U, E]']) -> 'Result[U, E]':
        return self

Result = Union[Ok[T], Err[E]]

def parse_int(s: str) -> Result[int, str]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int, str]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def print_result(result: Result[int, str]) -> None:
    match result:
        case Ok(value):
            print(f"Result: {value}")
        case Err(msg):
            print(f"Error: {msg}")

def main() -> None:
    res1 = parse_int("10").and_then(lambda n: divide_safe(n, 2))
    print_result(res1)

    res2 = parse_int("10").and_then(lambda n: divide_safe(n, 0))
    print_result(res2)

    res3 = parse_int("abc").and_then(lambda n: divide_safe(n, 2))
    print_result(res3)

if __name__ == "__main__":
    main()

