type Option[a] =
  | Some(a)
  | None

type LogEntry = {
  level: string,
  message_parts: List[string]
}

type LogStats = {
  total: int,
  info_count: int,
  error_count: int,
  warning_count: int,
  users: List[string]
}

func _list_contains(xs: List[string], x: string) -> bool {
  match xs {
    [] => false,
    ::(h, t) => if h == x then true else _list_contains(t, x)
  }
}

func _str_join(parts: List[string], sep: string) -> string {
  match parts {
    [] => "",
    ::(h, []) => h,
    ::(h, t) => h ++ sep ++ _str_join(t, sep)
  }
}

func insert_sorted(x: string, xs: List[string]) -> List[string] {
  match xs {
    [] => [x],
    ::(h, t) => if x < h then ::(x, xs) else ::(h, insert_sorted(x, t))
  }
}

func _list_sort(xs: List[string]) -> List[string] {
  match xs {
    [] => [],
    ::(h, t) => insert_sorted(h, _list_sort(t))
  }
}

func percentage(count: int, total: int) -> int {
  if total == 0
  then 0
  else floatToInt(intToFloat(count * 100) / intToFloat(total) + 0.5)
}

func parseLogLine(line: string) -> Option[LogEntry] {
  let parts = _str_split(line, " ");
  match parts {
    ::(_, ::(_, ::(level, message_parts))) =>
      if level == ""
      then None
      else Some({ level: level, message_parts: message_parts }),
    _ => None
  }
}

func extractUser(message_parts: List[string]) -> Option[string] {
  match message_parts {
    ::("User", ::("logged", ::("in:", ::(name, [])))) => Some(name),
    ::("User", ::("logged", ::("out:", ::(name, [])))) => Some(name),
    _ => None
  }
}

func updateStats(stats: LogStats, entry: LogEntry) -> LogStats {
  let temp_stats =
    if entry.level == "INFO" then { stats | info_count: stats.info_count + 1 }
    else if entry.level == "ERROR" then { stats | error_count: stats.error_count + 1 }
    else if entry.level == "WARNING" then { stats | warning_count: stats.warning_count + 1 }
    else stats;

  let user_opt = extractUser(entry.message_parts);

  let new_users = match user_opt {
    None => temp_stats.users,
    Some(user) =>
      if _list_contains(temp_stats.users, user)
      then temp_stats.users
      else ::(user, temp_stats.users)
  };

  { temp_stats | total: stats.total + 1, users: new_users }
}

func processLines(lines: List[string], stats: LogStats) -> LogStats {
  match lines {
    [] => stats,
    ::(line, rest) => {
      let new_stats = if line == "" then
        stats
      else
        match parseLogLine(line) {
          None => stats,
          Some(entry) => updateStats(stats, entry)
        };
      processLines(rest, new_stats)
    }
  }
}

