def transition(state: State, event: Event) -> State:
    """
    Calculates the next state based on the current state and event.
    This function implements the core logic of the state machine.
    """
    match (state, event):
        case (Green(timer), Tick()) if timer > 0:
            return Green(timer - 1)
        case (Green(_), Tick()):
            return Yellow(3)
        case (Yellow(timer), Tick()) if timer > 0:
            return Yellow(timer - 1)
        case (Yellow(_), Tick()):
            return Red(10)
        case (Red(timer), Tick()) if timer > 0:
            return Red(timer - 1)
        case (Red(_), Tick()):
            return Green(20)
        case (_, Reset()):
            return Green(20)

def show_state(state: State) -> str:
    """
    Returns a string representation of the given state.
