  match xs {
    [] => ys,
    ::(h, t) => h :: append(t, ys)
  }
}

func treeToList(tree: Tree) -> List[int] {
  match tree {
    Leaf(v) => [v],
    Node(l, v, r) => append(treeToList(l), v :: treeToList(r))
  }
}

func filter(pred: int -> bool, xs: List[int]) -> List[int] {
    match xs {
        [] => [],
        ::(h, t) => {
            let rest = filter(pred, t);
            if pred(h) then h :: rest else rest
        }
    }
}

func showList_inner(lst: List[int]) -> string {
  match lst {
    [] => "",
    [x] => show(x),
    ::(h, t) => show(h) ++ ", " ++ showList_inner(t)
  }
}

func showList(lst: List[int]) -> string {
  "[" ++ showList_inner(lst) ++ "]"
}

func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(l, v, r) => Node(mapTree(fn, l), fn(v), mapTree(fn, r))
  }
}

func foldTree(f: (int -> int -> int), acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => f(acc)(v),
    Node(l, v, r) => {
      let accLeft = foldTree(f, acc, l);
      let accV = f(accLeft)(v);
      foldTree(f, accV, r)
    }
  }
}

func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(l, _, r) => {
      let leftDepth = treeDepth(l);
      let rightDepth = treeDepth(r);
      1 + (if leftDepth > rightDepth then leftDepth else rightDepth)
    }
  }
}

export func main() -> () ! {IO} {
  let tree = Node(
    Node(Leaf(1), 3, Leaf(0)),
    5,
    Node(Leaf(7), 8, Leaf(9))
  );

  let isNotZero = \x. x != 0;

  let originalList = filter(isNotZero, treeToList(tree));
  print("Original: " ++ showList(originalList));

  let doubledTree = mapTree(\x. x * 2, tree);
  let doubledList = filter(isNotZero, treeToList(doubledTree));
  print("Doubled: " ++ showList(doubledList));

  let sum = foldTree(\a. \b. a + b, 0, tree);
  print("Sum: " ++ show(sum));

  let depth = treeDepth(tree);
  print("Depth: " ++ show(depth))
}

