from dataclasses import dataclass
from typing import Union, Callable, List, TypeVar

T = TypeVar('T')
U = TypeVar('U')

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    elif isinstance(tree, Node):
        return Node(
            left=map_tree(fn, tree.left),
            value=fn(tree.value),
            right=map_tree(fn, tree.right)
        )
    raise TypeError("Invalid tree node type")

def fold_tree(fn: Callable[[U, int], U], acc: U, tree: Tree) -> U:
    if isinstance(tree, Leaf):
        # Ignore dummy nodes with value 0 in the fold
        return acc if tree.value == 0 else fn(acc, tree.value)
    elif isinstance(tree, Node):
        left_acc = fold_tree(fn, acc, tree.left)
        val_acc = fn(left_acc, tree.value)
        right_acc = fold_tree(fn, val_acc, tree.right)
        return right_acc
    raise TypeError("Invalid tree node type")

def tree_to_list(tree: Tree) -> List[int]:
    if isinstance(tree, Leaf):
        # Ignore dummy nodes with value 0
        return [] if tree.value == 0 else [tree.value]
    elif isinstance(tree, Node):
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)
    raise TypeError("Invalid tree node type")

def tree_depth(tree: Tree) -> int:
    if isinstance(tree, Leaf):
        return 1
    elif isinstance(tree, Node):
        return 1 + max(tree_depth(tree.left), tree_depth(tree.right))
    raise TypeError("Invalid tree node type")

def main() -> None:
    example_tree: Tree = Node(
        left=Node(left=Leaf(1), value=3, right=Leaf(0)),
        value=5,
        right=Node(left=Leaf(7), value=8, right=Leaf(9))
    )

    original_list = tree_to_list(example_tree)
    print(f"Original: {original_list}")

    doubled_tree = map_tree(lambda x: x * 2, example_tree)
    doubled_list = tree_to_list(doubled_tree)
    print(f"Doubled: {doubled_list}")

    total_sum = fold_tree(lambda acc, val: acc + val, 0, example_tree)
    print(f"Sum: {total_sum}")

    depth = tree_depth(example_tree)
    print(f"Depth: {depth}")

if __name__ == "__main__":
    main()

